	/*
     * @param	event CreateAdjusterEvent
     */
    @EventHandler( payloadType=CreateAdjusterEvent.class )
    public void handle( CreateAdjusterEvent event) {
	    LOGGER.info("handling CreateAdjusterEvent - " + event );
	    Adjuster entity = new Adjuster();
            entity.setAdjusterId( event.getAdjusterId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setLicenseNumber( event.getLicenseNumber() );
            entity.setAdjusterType( event.getAdjusterType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAdjuster( entity );
    }

    /*
     * @param	event UpdateAdjusterEvent
     */
    @EventHandler( payloadType=UpdateAdjusterEvent.class )
    public void handle( UpdateAdjusterEvent event) {
    	LOGGER.info("handling UpdateAdjusterEvent - " + event );
    	
	    Adjuster entity = new Adjuster();
            entity.setAdjusterId( event.getAdjusterId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setLicenseNumber( event.getLicenseNumber() );
            entity.setClaims( event.getClaims() );
            entity.setServiceProviders( event.getServiceProviders() );
            entity.setAdjusterType( event.getAdjusterType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindAdjuster( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAdjuster( entity );        
    }
    
