    /**
     * Method to retrieve the Adjuster via an AdjusterPrimaryKey.
     * @param 	id Long
     * @return 	Adjuster
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Adjuster handle( FindAdjusterQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAdjusterId() );
    }
    
    /**
     * Method to retrieve a collection of all Adjusters
     *
     * @param	query	FindAllAdjusterQuery 
     * @return 	List<Adjuster> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Adjuster> handle( FindAllAdjusterQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAdjuster,
 * but only if the id matches
 *
 * @param		entity	Adjuster
 */
	protected void emitFindAdjuster( Adjuster entity ) {
		LOGGER.info("handling emitFindAdjuster" );
		
	    queryUpdateEmitter.emit(FindAdjusterQuery.class,
	                            query -> query.getFilter().getAdjusterId().equals(entity.getAdjusterId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAdjuster
	 * 
	 * @param		entity	Adjuster
	 */
	protected void emitFindAllAdjuster( Adjuster entity ) {
		LOGGER.info("handling emitFindAllAdjuster" );
		
	    queryUpdateEmitter.emit(FindAllAdjusterQuery.class,
	                            query -> true,
	                            entity);
	}

